#!/bin/bash
cd "$(dirname "$0")/.." || exit 1
F="FACE PASS (user request): the in-game FACES do not match the original art. Compare the face region of the current model (render the preview, and make a close-up if needed; the head cube front/side faces are painted in tools/bbgen/chars/<name>.py) with the confirmed art, then repaint the face texture and fix the face-related geometry (bangs/fringe covering the face, eye shapes, mouth size and teeth, eye glow, expression, hair framing) so the head reads like the reference. ONLY change faces: keep every attack/animation/ability, the overall silhouette, hitboxes and cube names. After regenerating with the script, re-apply the size from docs/HEIGHTS.md with tools/bbgen/rescale.py (check the max cube top y before/after is unchanged). Verify with the preview image and compare with the reference."
tools/run_agent.sh miss_circle MissCircle "$F Miss Circle specifically: refs docs/ref/confirmed/miss_circle_face_a.png (left: red-lit frame, right: blue-lit frame) and miss_circle_face_b.png (eye close-up with a star glint) plus miss_circle.jpg: long black hair framing the face, one eye hidden/squinting under the hair, the other large with a bright glint, a wide SHARP-TOOTH grin (many small triangular teeth), pale face, bow tie at the collar. The current face is wrong."
tools/run_agent.sh fen Fen "$F Fen specifically: refs docs/ref/confirmed/fen_face_ref.png (left: the orange fringe/bangs cover nearly the whole face, one dark eye barely showing; right: head close-up with the big triangular bangs) and fen_new.jpg. docs/ref/confirmed/fen_face_wrong_ingame.png is what the model looks like NOW and is WRONG (huge toothy mouth and big round eye): the face must be mostly hidden under the orange bangs, small dark eye, small mouth/ sharp grin only partly visible."
tools/run_agent.sh red_circle RedCircle "$F Audit these characters, fix only those whose face clearly differs from their confirmed art (docs/ref/confirmed/<name>.jpg): red_circle, miss_thavel, miss_bloomie, danger_thavel, danger_bloomie, green_thavel, green_bloomie, green_circle."
tools/run_agent.sh alice Alice "$F Audit these characters, fix only those whose face clearly differs from their confirmed art: alice (phase 1; docs/ref/confirmed/alice_phase1.jpg), danger_alice (danger_alice_phase1.jpg), green_alice (green_alice_phase1.png), daniel_barrel (daniel_barrel_matured.png), riley (riley.png), aiden (aiden.jpg), hansel_juvenile (hansel_juvenile.png), lord_hansel (hansel_matured.png). Boss/phase-2 forms only if their face is clearly shown in the art."
tools/run_agent.sh mutant_claire MutantClaire "$F Audit these characters, fix only those whose face clearly differs from their confirmed art: mutant_claire, mutant_engel, mutant_bubble, mutant_lana, mutant_abbie (docs/ref/confirmed/mutant_*.png), infected_bloomie, infected_zip."
echo QUEUE_DONE
